export class Point { constructor(x, y) { this.y = y; this.x = x; } sum(k) { return this.x + this.y + k; } static of(x) { return new Point(x, x); } get first() { return this.x; } set first(v) { this.x = v; } }
export function Old(a) { if (!(this instanceof Old)) return new Old(a); this.a = a; }
Old.prototype.twice = function (k) { return [this.a, this.a, k.length]; };
Old.make = function (a) { return new Old(a); }
export class Factory { constructor(kind) { if (kind === "other") return { made: "another object" }; this.kind = kind; } who() { return this.kind; } }
export class Late { constructor(n) { if (n > 1) this.big = true; this.n = n; } grow(name) { this[name] = name; return Object.keys(this); } }
export class Sub extends Point { constructor(x) { super(x, "y of Sub"); this.extra = x; } sum(k) { return "Sub:" + super.sum(k); } }
export class Generic { constructor(held) { this.held = held; } get() { return this.held; } put(held) { this.held = held; return this; } }
export class Private { #held; constructor(held) { this.#held = held; } #twice(k) { return [this.#held, k]; } twice(k) { return this.#twice(k); } static is(o) { return #held in o; } }
export function takes_point(p) { return [p.x, p.y, typeof p.sum === "function" ? p.sum(1) : "no sum", p instanceof Point]; }
export function takes_old(o) { return [o.a, o instanceof Old]; }
export function takes_other_class(p) { return [p.x, p.a, p.kind]; }
export function writes_point(p) { p.x = "written"; p.w = 1; return Object.keys(p); }
export function makes_point(x) { return x === 1 ? new Point(1, 2) : x === 2 ? { x: "plain", y: 0 } : null; }
export function reads_made(x) { const p = makes_point(x); return p && [p.x, p.y]; }
